'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const budget = input[idx++];
const n = input[idx++];
const m = input[idx++];

const graph = Array.from({ length: n }, () => []);

for (let i = 0; i < m; i++) {
  const a = input[idx++] - 1;
  const b = input[idx++] - 1;
  const time = input[idx++];
  const cost = input[idx++];

  graph[a].push([b, time, cost]);
  graph[b].push([a, time, cost]);
}

const start = input[idx++] - 1;
const destination = input[idx++] - 1;

const width = budget + 1;
const dist = new Float64Array(n * width);
dist.fill(Infinity);

class MinHeap {
  constructor() {
    this.states = [];
    this.distances = [];
    this.lastDistance = 0;
  }

  push(state, distance) {
    let i = this.states.length;
    this.states.push(state);
    this.distances.push(distance);

    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.distances[parent] <= distance) break;
      this.states[i] = this.states[parent];
      this.distances[i] = this.distances[parent];
      i = parent;
    }

    this.states[i] = state;
    this.distances[i] = distance;
  }

  pop() {
    const state = this.states[0];
    this.lastDistance = this.distances[0];

    const lastState = this.states.pop();
    const lastDistance = this.distances.pop();

    if (this.states.length > 0) {
      let i = 0;
      const size = this.states.length;

      while (true) {
        const left = i * 2 + 1;
        if (left >= size) break;

        const right = left + 1;
        let child = left;
        if (right < size && this.distances[right] < this.distances[left]) {
          child = right;
        }

        if (this.distances[child] >= lastDistance) break;

        this.states[i] = this.states[child];
        this.distances[i] = this.distances[child];
        i = child;
      }

      this.states[i] = lastState;
      this.distances[i] = lastDistance;
    }

    return state;
  }
}

const heap = new MinHeap();
const startState = start * width;
dist[startState] = 0;
heap.push(startState, 0);

let answer = -1;

while (heap.states.length > 0) {
  const state = heap.pop();
  const currentTime = heap.lastDistance;

  if (currentTime !== dist[state]) continue;

  const island = Math.floor(state / width);
  const spent = state % width;

  if (island === destination) {
    answer = currentTime;
    break;
  }

  for (const [nextIsland, travelTime, travelCost] of graph[island]) {
    const nextSpent = spent + travelCost;
    if (nextSpent > budget) continue;

    const nextState = nextIsland * width + nextSpent;
    const nextTime = currentTime + travelTime;

    if (nextTime < dist[nextState]) {
      dist[nextState] = nextTime;
      heap.push(nextState, nextTime);
    }
  }
}

console.log(answer);
